import fs from 'node:fs';
const urls=['https://mainnet.base.org','https://base.public.blockpi.network/v1/rpc/public'];
const from=52849852, vault='0xe48699b8401564aace7a814ae4569b67a3f7eef5';
const out={checkedAt:new Date().toISOString(),fromBlock:from,vault,complete:false,providers:[]};
async function rpc(u,method,params){const r=await fetch(u,{method:'POST',redirect:'error',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error(`HTTP ${r.status} ${new URL(u).hostname}`);const b=await r.text();if(b.length>2097152)throw Error('oversized response');const d=JSON.parse(b);if(d.error)throw Error(JSON.stringify(d.error));return d.result;}
const both=(m,p)=>Promise.all(urls.map(u=>rpc(u,m,p)));
try{const chains=await both('eth_chainId',[]);if(chains.some(c=>c!=='0x2105'))throw Error('wrong chain');const heads=await both('eth_blockNumber',[]);const to=Math.min(...heads.map(h=>Number(h)))-12;if(to-from>30000)throw Error('delta exceeds bounded scan');const blocks=await both('eth_getBlockByNumber',['0x'+to.toString(16),false]);if(!blocks[0]||blocks.some(b=>b.hash!==blocks[0].hash))throw Error('block disagreement');Object.assign(out,{toBlock:to,blockHash:blocks[0].hash});const events=[];for(let lo=from;lo<=to;lo+=5000){const rows=await both('eth_getLogs',[{address:vault,fromBlock:'0x'+lo.toString(16),toBlock:'0x'+Math.min(lo+4999,to).toString(16)}]);const clean=rows.map(rs=>rs.map(x=>({blockNumber:x.blockNumber,blockHash:x.blockHash,transactionHash:x.transactionHash,logIndex:x.logIndex,topics:x.topics})).sort((a,b)=>Number(a.blockNumber)-Number(b.blockNumber)||Number(a.logIndex)-Number(b.logIndex)));if(JSON.stringify(clean[0])!==JSON.stringify(clean[1]))throw Error('event disagreement');events.push(...clean[0]);}Object.assign(out,{complete:true,eventCount:events.length,events,providers:urls});}catch(e){out.error=String(e.message).slice(0,240);}
fs.writeFileSync('outputs/custody-existing-contracts/recent-event-audit-node.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out,null,2));
